// <auto-generated/>
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Collections;

namespace Fanex.Age.Utility.CaptchaUtil
{
    public static class CaptchaLogging
    {
        private const int MAX_LIST_SIZE = 10000;
        private static List<CaptchaInfo> sCaptchaList = new List<CaptchaInfo>();
        private static object lockObj = new object();

        public static void Log(string ip, string username, CaptchaType type)
        {
            // only logging in question
            if (type == CaptchaType.Question)
            {
                CaptchaInfo info = Find(ip, username);
                if (info == null)
                {
                    info = new CaptchaInfo
                    {
                        Ip = ip,
                        Username = username,
                        Type = type
                    };
                    lock (lockObj)
                    {
                        sCaptchaList.Add(info); // add last
                        while (sCaptchaList.Count > MAX_LIST_SIZE)
                        {
                            sCaptchaList.RemoveAt(0); // remove first
                        }
                    }
                }
            }
        }

        public static void RemoveLog(string ip, string username)
        {
            CaptchaInfo info = Find(ip, username);
            if (info != null)
            {
                lock (lockObj)
                {
                    sCaptchaList.Remove(info);
                }
            }
        }

        public static CaptchaInfo Find(string ip, string username)
        {
            lock (lockObj)
            {
                foreach (var info in sCaptchaList)
                {
                    if (info.Ip == ip || string.Equals(info.Username, username, StringComparison.CurrentCultureIgnoreCase))
                    {
                        return info;
                    }
                }
            }
            return null;
        }
    }
}
